<?php
require __DIR__ . '/../app/bootstrap.php'; $user = require_user();
$completed = query('SELECT lesson_id FROM progress WHERE user_id = ?', [$user['id']])->fetchAll(PDO::FETCH_COLUMN);
$curriculum = lessons(); $completed = array_values(array_intersect($completed, array_keys($curriculum)));
$count = count($completed); $percent = (int)round($count / count($curriculum) * 100);
$nextId = null; foreach ($curriculum as $id => $lesson) { if (!in_array($id, $completed, true)) { $nextId = $id; break; } }
$activities = query('SELECT description, created_at FROM activity WHERE user_id = ? ORDER BY id DESC LIMIT 4', [$user['id']])->fetchAll();
$firstName = explode(' ', $user['name'])[0]; render_header('My workspace', 'dashboard', $user);
?>
<main class="workspace container" id="main"><?php workspace_nav('dashboard', $user); ?><div class="workspace-main"><div class="workspace-heading"><div><p class="eyebrow">YOUR SPACE TO GROW</p><h1>Hello, <?= e($firstName) ?><span class="greeting-star" aria-hidden="true">✳</span></h1><p class="muted"><?= $count === 4 ? 'Look how far you’ve come. Keep your curiosity going.' : 'A little progress today is a little more possibility tomorrow.' ?></p></div><span class="member-tag">STUDIO MEMBER</span></div>
<section class="next-step-card"><div><span class="eyebrow"><?= $nextId ? 'YOUR NEXT SMALL STEP' : 'A CHAPTER COMPLETED' ?></span><h2><?= $nextId ? e($curriculum[$nextId]['title']) : 'You made it through the path.' ?></h2><p><?= $nextId ? 'Open your next lesson, try the activity, and check what you’ve learned.' : 'Four lessons. Four new perspectives. Revisit a lesson or explore the resource shelf.' ?></p><a class="button" href="<?= $nextId ? 'lesson.php?id=' . e($nextId) : 'resources.php' ?>"><?= $count === 0 ? 'Start learning' : ($nextId ? 'Continue learning' : 'Explore more') ?> <?= icon('arrow') ?></a></div><div class="next-step-art" aria-hidden="true"><span class="code-brace">{</span><span class="large-star">✳</span><span class="code-brace">}</span><small>MAKE SOMETHING POSSIBLE</small></div></section>
<div class="stat-cards"><article><span class="eyebrow">YOUR PROGRESS</span><div class="stat-value"><?= $percent ?><span>%</span></div><progress max="4" value="<?= $count ?>" aria-label="Learning path progress"><?= $percent ?>%</progress><p><?= $count ?> of 4 lessons completed</p></article><article><span class="eyebrow">SMALL WINS</span><div class="stat-value"><?= str_pad((string)$count, 2, '0', STR_PAD_LEFT) ?><span>/ 04</span></div><p>Every finished lesson is a step forward.</p></article><article class="goal-card"><span class="eyebrow">YOUR NORTH STAR</span><h3><?= e($user['goal']) ?></h3><a href="profile.php">Adjust your goal <?= icon('arrow') ?></a></article></div>
<section class="learning-section" id="learning-path"><div class="section-heading tight"><div><p class="eyebrow">THE FOUNDATIONS</p><h2>Your learning path</h2></div><span class="muted">4 lessons · about 1 hour</span></div><div class="lesson-list"><?php foreach ($curriculum as $id => $lesson): $done = in_array($id, $completed, true); ?><a class="lesson-row <?= $done ? 'done' : '' ?>" href="lesson.php?id=<?= e($id) ?>"><span class="lesson-number"><?= $done ? icon('check') : e($lesson['number']) ?></span><div><span class="eyebrow"><?= e($lesson['topic']) ?> · <?= e($lesson['minutes']) ?> MIN</span><h3><?= e($lesson['title']) ?></h3></div><span class="lesson-status"><?= $done ? 'Completed' : ($id === $nextId ? 'Up next' : 'Explore') ?></span><?= icon('arrow') ?></a><?php endforeach; ?></div></section>
<section class="workspace-bottom"><article class="activity-card"><p class="eyebrow">LITTLE MOMENTS THAT ADD UP</p><h2>Your recent activity</h2><ul><?php foreach ($activities as $activity): ?><li><span class="activity-dot"></span><div><?= e($activity['description']) ?><time datetime="<?= e($activity['created_at']) ?>"><?= e(date('j M Y · H:i', strtotime($activity['created_at'] . ' UTC'))) ?></time></div></li><?php endforeach; ?></ul></article><article class="resource-promo"><span class="tiny-star" aria-hidden="true">↗</span><p class="eyebrow">FEED YOUR CURIOSITY</p><h2>A shelf full<br>of possibilities.</h2><p>Trusted guides for whatever you want to make next.</p><a class="text-link" href="resources.php">Browse resources <?= icon('arrow') ?></a></article></section>
</div></main><?php render_footer(); ?>
